def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) != len(edges) - 1:
        raise ValueError("the number of bins and edges must match exactly")

    if len(bins[0]) != len(edges):
        raise ValueError("variable array length must match histogram.edges length")

    result = [0] * len(edges) - 1

    for i in range(len(edges) - 1):
        if i == 0:
            result[i] = edges[i + 1] - bins[i][0]
        elif i == len(edges) - 2:
            result[i] = bins[i][1] - edges[i]
        else:
            result[i] = bins[i + 1][1] - bins[i][0]

    return result

