def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application's manifest is not empty
    if not app.spec.manifest:
        raise ValueError("The application's manifest is empty. Please provide a valid application manifest.")

    # Define the schema for an observer
    observer_schema = {
        "type": "object",
        "properties": {
            "resource": {"type": "string"},
            "status": {"type": "string"}
        },
        "required": ["resource", "status"]
    }

    # Iterate over the manifest and generate observer schemas for each resource
    observer_schemas = {}
    for resource in app.spec.manifest:
        # Generate a unique schema for each resource
        observer_schemas[resource] = {
            "type": "object",
            "properties": {
                "resource": {"type": "string"},
                "status": {"type": "string"}
            },
            "required": ["resource", "status"],
            "allOf": [
                observer_schema
            ]
        }

    # Return the dictionary of observer schemas
    return observer_schemas

