def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    try:
        if extract_spec_version:
            if inventory.type:
                self.spec_version = inventory.type
            else:
                raise ValueError("Type value is required for validating the inventory.")
        else:
            self.spec_version = self._get_spec_version_from_inventory(inventory)

        self.inventories = inventory.copy()
        self.latest = self.inventories.pop(self.id)

        for inventory_id, new_inventory in self.inventories.items():
            # validate each new inventory against the existing one
            for new_item in new_inventory:
                for existing_item in self.latest.hydrate(new_item.attributes, inventory_id=inventory_id):
                    if new_item.id != existing_item.id:
                        if new_item.id in existing_item.linked:
                            if existing_item.linked[new_item.id] != new_item:
                                raise ValueError(f"Duplicate linked item found: {existing_item.linked[new_item.id]} vs {new_item}")
                        else:
                            existing_item.linked[new_item.id] = new_item

    except ValueError as e:
