def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("Input value must be an integer")
    ifalphabet is None or len(alphabet) == 0:
        raise ValueError("Alphabet must be non-empty")

    digits = []
    if number == 0:
        return "0"

    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        digits.extend('0' * max(0, padding - len(digits)))

    return ''.join(reversed(digits))

