import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform is 'this':
        if sys.platform == 'win32' or sys.platform == 'cygwin':
            sed = re.compile('[^a-zA-Z0-9_./\\-]')
        else:
            sed = re.compile('[^a-zA-Z0-9_:_+/\\-]')
    elif platform == 1:
        sed = re.compile('[^a-zA-Z0-9_\.\/\\-]')
    elif platform == 0 or platform is False:
        sed = re.compile('[^a-zA-Z0-9_:_+/\\-]')
    else:
        raise ValueError('Invalid platform value: ' + str(platform))

    # Splitting by a RegEx pattern, excluding the XML namespace tag
    elements = re.split(sed, re.escape(s), flags=re.UNICODE|re.DOTALL)
    return elements[:-1] #No empty element

